import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;

public class DocumentTest {

    @Test
    public void createShellDocument() {
        String baseUri = "https://www.example.com";
        Document document = Document.createShell(baseUri);
        assertNotNull(document);
    }

    @Test
    public void createShellEmptyDocument() {
        String baseUri = "";
        Document document = Document.createShell(baseUri);
        assertEquals("", document.outerHtml());
    }

    @Test
    public void locationMethodReturnsCorrectLocation() {
        String baseUri = "https://www.example.com";
        Document document = new Document(baseUri);
        assertEquals("https://www.example.com", document.location());
    }

    @Test
    public void connectionMethodReturnsCorrectConnection() {
        String baseUri = "https://www.example.com";
        Connection connection = Jsoup.connect(baseUri);
        Document document = new Document(connection);
        assertNotNull(document.connection());
    }

    @Test
    public void expectFormMethodReturnsCorrectFormElement() {
        String cssQuery = "#form";
        List<FormElement> forms = new ArrayList<>();
        FormElement formElement = new FormElement();
        forms.add(formElement);
        Document document = new Document();
        assertEquals(formElement, document.expectForm(cssQuery));
    }

    @Test
    public void titleMethodReturnsCorrectTitle() {
        String title = "Example Title";
        Document document = new Document();
        document.title(title);
        assertEquals(title, document.title());
    }

    @Test
    public void createElementMethodCreatesCorrectTag() {
        String tagName = "p";
        Element tag = new Document().createElement(tagName);
        assertNotNull(tag);
    }

    @Test
    public void outerHtmlReturnsCorrectOuterHtml() {
        String html = "<html><body>Hello World!</body></html>";
        Document document = Jsoup.parse(html);
        assertEquals(html, document.outerHtml());
    }

    @Test
    public void textMethodSetsCorrectTextContent() {
        String text = "Hello World!";
        Document document = new Document();
        document.text(text);
        assertEquals(text, document.text());
    }

    @Test
    public void nodeNameReturnsCorrectNodeName() {
        Element tag = new Tag("p");
        Document document = new Document(tag);
        assertEquals("p", document.nodeName());
    }

    @Test
    public void charsetMethodSetsCorrectCharset() {
        Charset charset = Charset.forName("UTF-8");
        Document document = new Document();
        document.charset(charset);
        assertEquals(charset, document.charset());
    }

    @Test
    public void updateMetaCharsetElementMethodUpdatesCorrectMetaTag() {
        boolean update = true;
        Document document = new Document();
        document.updateMetaCharsetElement(update);
        assertTrue(document.updateMetaCharsetElement());
    }

    @Test
    public void outputSettingsMethodReturnsCorrectOutputSettings() {
        OutputSettings outputSettings = OutputSettings.createDefault();
        Document document = new Document(outputSettings);
        assertNotNull(document.outputSettings());
    }

    @Test
    public void quirksModeMethodSetsCorrectQuirksMode() {
        QuirksMode quirksMode = QuirksMode.MAXIMIZE;
        Document document = new Document();
        document.quirksMode(quirksMode);
        assertEquals(quirksMode, document.quirksMode());
    }

    @Test
    public void shallowCloneMethodReturnsCorrectShallowClone() {
        String html = "<html><body>Hello World!</body></html>";
        Document document = Jsoup.parse(html).clone();
        assertNotNull(document.shallowClone());
    }

    @Test
    public void parserMethodReturnsCorrectParser() {
        Parser parser = Parser.createDefault();
        Document document = new Document();
        document.parser(parser);
        assertNotNull(document.parser());
    }
}
